SourceCode.Declaration:
/// <summary>
/// The TFMDescriptionAttribute class is an attribute to register with your classes, that describes their purpose
/// </summary>
public class TFMDescriptionAttribute extends SysAttribute implements SysExtensionIAttribute
{
    Description255       description;

}

Method.Source:
///<summary>
/// Returns the key used for storing cached data for this attribute.
/// </summary>
/// <returns>
/// A string representing the cache key.
/// </returns>
public str parmCacheKey()
{
    return classStr(TFMDescriptionAttribute)+';'+description;
}

public Description255 parmDescription(Description255 _description = description)
{
    description = _description;

    return description;
}

///<summary>
/// Determines if the same instance should be returned by the extension framework.
/// </summary>
/// <returns>
/// true if the same instance should be returned; otherwise false.
/// </returns>
public boolean useSingleton()
{
    return false;
}
